public class ParallelPhases
{
    private readonly Barrier _barrier;
    private int _phase1Result;
    private int _phase2Result;

    public ParallelPhases(int participantCount)
    {
        _barrier = new Barrier(participantCount, b =>
        {
            Console.WriteLine($"Phase {b.CurrentPhaseNumber} complete");
        });
    }

    public void RunPhase1()
    {
        _phase1Result = Compute();
        _barrier.SignalAndWait();
    }

    public void RunPhase2()
    {
        _phase2Result = _phase1Result * 2;
        _barrier.SignalAndWait();
    }
}
